mapper.select:
SELECT FROM CLOUDWALK.DEVICE
ORDER BY ${params.sortField} ${params.sortOrder}
OFFSET #{params.current} ROWS FETCH NEXT #{params.pageSize} ROWS ONLY

SELECT 
FROM CLOUDWALK.DEVICE
WHERE ID = #{id}

SELECT 
FROM CLOUDWALK.DEVICE

    
        AND DEVICE_CODE = #{params.deviceCode}
    
    
        AND DEVICE_NAME LIKE '%' || #{params.deviceName} || '%'
    
    
        AND TOURISM_NAME = #{params.tourismName}
    
    
        AND STATUS = #{params.status}
    
    
        AND CREATE_TIME >= #{params.startTime}
    
    
        AND CREATE_TIME <= #{params.endTime}
    

ORDER BY CREATE_TIME DESC
OFFSET #{params.offset} ROWS FETCH NEXT #{params.limit} ROWS ONLY

SELECT 

FROM DEVICE

    
        AND DEVICE_CODE = #{deviceCode}
    
    
        AND DEVICE_NAME LIKE '%' || #{deviceName} || '%'
    
    
        AND TOURISM_NAME = #{tourismName}
    
    
        AND STATUS = #{status}
    

ORDER BY CREATE_TIME DESC

SELECT 

FROM DEVICE
WHERE DEVICE_CODE = #{deviceCode}

SELECT STATUS as status, COUNT(*) as count FROM DEVICE
AND TOURISM_NAME = #{tourismName}
GROUP BY STATUS

mapper.insert:
INSERT INTO DEVICE (
    DEVICE_CODE, DEVICE_NAME, TOURISM_NAME, STATUS
) VALUES (
    #{deviceCode}, #{deviceName}, #{tourismName}, #{status}
)

mapper.select:
SELECT COUNT(*)
FROM CLOUDWALK.DEVICE

    
        AND TOURISM_NAME = #{params.tourismName}
    
    
        AND DEVICE_CODE = #{params.deviceCode}
    
    
        AND DEVICE_TYPE = #{params.deviceType}
    
    
        AND STATUS = #{params.status}

SELECT

FROM CLOUDWALK.DEVICE
WHERE TOURISM_NAME = #{tourismName}
AND DEVICE_TYPE = #{deviceType}
ORDER BY CREATE_TIME DESC

SELECT

FROM CLOUDWALK.DEVICE
WHERE TOURISM_NAME = #{tourismName}
AND STATUS = #{status}
ORDER BY CREATE_TIME DESC

SELECT

FROM CLOUDWALK.DEVICE
WHERE DEVICE_TYPE = #{deviceType}
AND STATUS = #{status}
ORDER BY CREATE_TIME DESC
